@Override public synchronized State waitUntilFinish(){
  if (job != null) {
    try {
      job.join();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt(); // 恢复中断状态
      e.printStackTrace();
      return State.FAILED;
    }
    state=getState(job);
  }
  return state;
}
